import{_ as e,c as t,o as i,a as n}from"./app.c62f2221.js";const m=JSON.parse('{"title":"Math 301: Convex Optimization","description":"","frontmatter":{},"headers":[{"level":2,"title":"General Information","slug":"general-information"},{"level":2,"title":"Course Description","slug":"course-description"},{"level":2,"title":"Prerequisites","slug":"prerequisites"},{"level":2,"title":"Textbooks","slug":"textbooks"},{"level":2,"title":"Grading","slug":"grading"}],"relativePath":"teaching/convex/index.md"}'),o={name:"teaching/convex/index.md"},r=n('<h1 id="math-301-convex-optimization" tabindex="-1">Math 301: Convex Optimization <a class="header-anchor" href="#math-301-convex-optimization" aria-hidden="true">#</a></h1><div class="info custom-block"><p class="custom-block-title">Announcements</p><p><strong>Spring 2026</strong>: Welcome to Math 301. The first lecture will be held on Monday, Jan 26. Please sign up for the course on Canvas to access submission links.</p></div><h2 id="general-information" tabindex="-1">General Information <a class="header-anchor" href="#general-information" aria-hidden="true">#</a></h2><table><thead><tr><th style="text-align:left;"></th><th style="text-align:left;"></th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Instructor</strong></td><td style="text-align:left;"><strong>Yongli Zhu</strong> (<a href="mailto:yongliz@tamu.edu">yongliz@tamu.edu</a>)<br>Office: WEB 320G, TAMU</td></tr><tr><td style="text-align:left;"><strong>Lectures</strong></td><td style="text-align:left;">Mon/Wed 10:00 AM \u2013 11:30 AM<br>Engineering Building, Room 101</td></tr><tr><td style="text-align:left;"><strong>Office Hours</strong></td><td style="text-align:left;">Friday 2:00 PM \u2013 4:00 PM (WEB 320G)</td></tr><tr><td style="text-align:left;"><strong>TAs</strong></td><td style="text-align:left;">TBD</td></tr></tbody></table><h2 id="course-description" tabindex="-1">Course Description <a class="header-anchor" href="#course-description" aria-hidden="true">#</a></h2><p>The course concentrates on recognizing and solving convex optimization problems that arise in engineering, statistics, and financial modeling. The goal is to develop the skills and background needed to recognize, formulate, and solve convex optimization problems.</p><p><strong>Major topics include:</strong></p><ul><li>Convex sets and functions</li><li>Linear, quadratic, geometric, and semidefinite programming</li><li>Duality theory</li><li>Approximation and fitting</li><li>Statistical estimation</li><li>Geometric problems</li></ul><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-hidden="true">#</a></h2><p>Good knowledge of linear algebra and basic probability. Exposure to numerical computing (Python/MATLAB) is helpful.</p><h2 id="textbooks" tabindex="-1">Textbooks <a class="header-anchor" href="#textbooks" aria-hidden="true">#</a></h2><p>The course will adhere closely to the following text:</p><ul><li><strong>[BV]</strong>: <em>Convex Optimization</em> by Stephen Boyd and Lieven Vandenberghe. (<a href="https://web.stanford.edu/~boyd/cvxbook/" target="_blank" rel="noopener noreferrer">Download PDF</a>)</li></ul><p>Additional references:</p><ul><li><em>Vectors, Matrices, and Least Squares</em> by Stephen Boyd and Lieven Vandenberghe.</li><li><em>Introductory Lectures on Convex Optimization</em> by Y. Nesterov.</li></ul><h2 id="grading" tabindex="-1">Grading <a class="header-anchor" href="#grading" aria-hidden="true">#</a></h2><ul><li><strong>Homework (30%)</strong>: Assigned weekly, due on Fridays.</li><li><strong>Midterm Exam (30%)</strong>: 24-hour take-home exam.</li><li><strong>Final Project (40%)</strong>: Students will work in pairs to formulate and solve an optimization problem arising in their own research.</li></ul><br><div style="display:flex;justify-content:flex-end;margin-top:2rem;"><a href="./lectures" style="font-size:1.1em;font-weight:bold;color:var(--vp-c-brand);"> Next: Lectures &amp; Handouts \u2192 </a></div>',19),a=[r];function l(s,d,c,g,h,u){return i(),t("div",null,a)}var f=e(o,[["render",l]]);export{m as __pageData,f as default};
